import{_ as i,l,o as t,c as n,v as e,p as s,x as o,d,i as h,S as T}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"稼动率与 MTBF","description":"","frontmatter":{"title":"稼动率与 MTBF","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-uptime-mtbf.md","filePath":"litho/tool-uptime-mtbf.md","lastUpdated":1789023840000}'),p={name:"litho/tool-uptime-mtbf.md"};function m(_,a,c,B,u,f){const r=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="稼动率与-mtbf" tabindex="-1">稼动率与 MTBF <a class="header-anchor" href="#稼动率与-mtbf" aria-label="Permalink to &quot;稼动率与 MTBF&quot;">​</a></h1><div class="epigraph"><p>WPH 是理想节拍。稼动率把故障、校准、换版、等片乘进去。MTBF 决定你敢不敢把关键层绑在一台上。</p><footer>—— 对照 SEMI E10 稼动分类；[扫描仪产能](/litho/scanner-throughput)</footer></div><p><a href="/litho/tool-matching">上一课</a>让多机可混。缺口是单机到底在不在产。本课钉稼动与 MTBF，配方软件下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>产能表用峰值 WPH，财务用出片。停机：激光、浸没头、台、源。预防维护和校准吃掉日历时间。把「激光功率不够」写成唯一瓶颈，会漏可用性。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SEMI 时间分类：生产、待机、工程、计划停、非计划停。MTBF / MTTR 分子系统。双台掩盖装载，掩盖不了激光换管。备件与远程诊断进 MTTR。与训练集群的故障率课无关；本课是曝光机可用性。</p>',7)),(t(),s(T,null,{default:o(()=>[h(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20WPH%5B%22%E5%B3%B0%E5%80%BC%E7%89%87%2F%E5%B0%8F%E6%97%B6%22%5D%20--%3E%20AVAIL%5B%22%E7%A8%BC%E5%8A%A8%22%5D%0A%20%20AVAIL%20--%3E%20OUT%5B%22%E5%87%BA%E7%89%87%22%5D%0A%20%20MTBF%5B%22MTBF%22%5D%20--%3E%20AVAIL%0A%20%20MTTR%5B%22MTTR%22%5D%20--%3E%20AVAIL%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可用性 \\(\\approx\\) MTBF / (MTBF + MTTR) 再扣计划停。浸没与 EUV 源把 MTBF 拉低，所以产线用集群而不是单机神话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课软件：很多「故障」是配方和联机状态机，不是硬件 MTBF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>出片 = 峰值 WPH × 稼动，两项分开管。</li><li>MTBF 按子系统报，才能决定备件与冗余。</li><li>出处：SEMI E10；产能课。</li></ul>',6))])}const E=i(p,[["render",m]]);export{A as __pageData,E as default};
